#!/usr/bin/env python3
"""Independently author the Hist Ka root question bank."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/"questions/social";LESSON="lesson-social-content-hist-ka";KG="kg-social-content-hist-ka"
ITEMS=[
("二十世紀初有人以共和制度說明國家已現代化，但地方行政、軍隊與財政仍由不同勢力掌握。研究者應如何判讀？",["共和名稱與制度文本不等於全境制度落實，應比較中央、地方與不同時段的實際運作。","只要有憲法就能證明所有人享有相同政治權利。","地方差異不重要，因為現代國家只能由中央定義。","後來的政治結果已決定當時共和必然成功。"],"A","國家建立包含制度形式、治理能力和權利落地，不能以名稱或文本單獨判定。"),
("民族主義刊物號召共同國族，地方社團卻以方言、地域和職業組織動員。最完整的分析是？",["地方社團表示民族主義完全失敗。","國族想像可能透過地方組織被翻譯和動員，兩者可並存也可能產生張力。","只有中央刊物才代表真正國族。","方言存在就代表人們沒有任何共同認同。"],"B","共同國族與地方身分不是必然互斥，需分析動員方式、群體位置和實際政治關係。"),
("同一政府以選舉宣稱取得合法性，卻限制部分群體參與並以軍事命令處理反對聲音。研究時應？",["只看選舉是否舉行。","把政府宣稱直接當成所有人民的認同。","分開合法性主張、參與規則與實際權力，檢查誰被納入、誰被排除。","因為有排除，就否定所有制度變化。"],"C","合法性不只是一項宣稱，還要看制度規則、參與範圍與權力實作。"),
("科學教育、共和制度與社會革命在報刊中被不同群體賦予不同意義。哪種方法較適合比較？",["只比較口號出現的次數。","以後來的標準判定哪一種意義才正確。","把所有主張平均成相同意思。","比較作者位置、受眾、時段與政治目標，說明同一概念如何被不同群體使用。"],"D","政治概念的意義會隨群體、時空與目標改變，不能只做詞語統計或事後裁決。"),
("中央推行統一稅制，地方商會要求保留部分地方財源，農民則反映徵收負擔。最合理的結論是？",["現代國家形成同時涉及財政集中、地方協商與民眾成本，不能只寫中央成功。","商會和農民的材料與國家建立無關。","地方有要求就表示中央完全失去權力。","稅制只有行政功能，不會影響社會關係。"],"A","財政制度是國家能力和社會利益的交界，需同時看集中、協商與負擔。"),
("一份國族教科書宣稱全國共享相同歷史，地方學校教材卻加入當地人物與事件。研究者應？",["只採用中央教科書，地方教材是錯誤。","只採用地方教材，中央敘事沒有價值。","比較教材編寫目的、內容選擇與使用場域，分析共同敘事如何與地方記憶交織。","把兩份教材逐句拼接成唯一版本。"],"C","教材是國族塑造和地方記憶的材料，差異可揭示選擇、權力與使用情境。"),
("群眾集會同時出現學生、工人、商人與知識分子，但各群體的訴求和承擔風險不同。如何分析？",["只看集會人數，不必區分群體。","比較共同口號、個別利益、資源與風險，分析聯盟如何形成又可能如何分裂。","把所有參與者視為有完全相同的目標。","只記錄最有名的領袖。"],"B","群眾動員可能形成跨群體聯盟，但共同參與不等於利益、資源與風險完全相同。"),
("地方檔案顯示新制度只在城市執行，鄉村仍沿用舊有中介。最謹慎的判讀是？",["制度已在全國完成，鄉村資料只是例外。","制度推行具有空間與時間差異，應查交通、行政資源和地方中介如何影響落地。","鄉村沿用舊制表示沒有任何現代國家形成。","城市資料能直接代表所有地區。"],"B","制度落地受行政能力、交通和地方關係影響，不能由單一城市外推全國。"),
("研究者用革命宣言解釋國家建立，卻沒有查軍隊、稅收、學校和地方行政資料。主要問題是？",["宣言不屬於歷史資料。","國家建立只需要看思想，不需要制度資料。","宣言可呈現理想與動員語言，但不能單獨證明治理能力和制度實施。","只要補更多宣言就能解決。"],"C","政治宣言能說明主張與動員，治理是否落實仍需制度與地方證據互證。"),
("比較共和、民族、民主與科學等主張時，哪項最能避免把現代國家追求寫成單一路徑？",["將所有主張排成由落後到進步的固定階梯。","以單一領袖的方案代表整個社會。","只看最後建立的制度，不看爭論和代價。","把主張、制度選擇、動員方式和實際後果放在時序中比較，保留不同道路與未完成部分。"],"D","現代國家是多方爭論和制度試驗的過程，必須同時看理念、權力、動員與後果。"),
]
SOURCES=[{"url":"https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E7%9A%84%E7%A4%BE%E6%9C%83.pdf","title":"高雄市立鹽埕國民中學公開段考社會科；僅研究制度、政治變遷與資料判讀題型，未複製原題。","year":"114","locator":"公開段考社會科 PDF；第 1 題至第 10 題型範圍：制度、動員與因果界線","observedPattern":"由制度、主張與多方材料要求學生分析政治合法性、群體差異與證據範圍。"},{"url":"https://affairs.kh.edu.tw/1126/upload/file_list/149","title":"高雄市立文府國民中學公開社會科試題入口；僅研究多資料互證題型，未複製原題。","year":"113-114","locator":"公開試題與解答入口；第 1 題至第 10 題型範圍：國家、社會變遷與多重證據","observedPattern":"比較制度文本、地方記錄與群體觀點，區分直接記錄、推論與待補證主張。"},{"url":"https://www.dwm.kh.edu.tw/view/index.php?MainMenuId=64182&MainType=0&SubMenuId=64184&SubType=104&WebID=344","title":"高雄市立大灣國民中學公開段考試題入口；僅研究政治變遷與多方角色題型，未複製原題。","year":"113-114","locator":"公開段考試題入口；第 1 題至第 10 題型範圍：政治制度、文化變遷與多方角色","observedPattern":"從歷史情境分析制度、利益與社會變化，不以單一來源包辦結論。"}]
def refs():return[{**x,"subject":"social","reuseDecision":"pattern-only","status":"recorded","locatorLevel":"paper"}for x in SOURCES]
FOCUS=["共和政體與落地","民族主義與地方動員","合法性與政治參與","制度主張與概念使用","財政集中與群體成本","國族教材與地方記憶","跨群體公共動員","制度推行的空間差異","宣言與治理證據","多道路與制度選擇"]
for i,(prompt,opts,ans,reason) in enumerate(ITEMS,1):
 p=OUT/f"question-social-content-hist-ka-{i}.json";d=json.loads(p.read_text(encoding="utf-8"));assert d["lessonId"]==LESSON and d["knowledgeIds"]==[KG]
 focus=FOCUS[i-1]; d["prompt"]=prompt;d["options"]=[{"id":chr(65+j),"text":x}for j,x in enumerate(opts)];d["answer"]={"value":ans,"explanation":f"本題聚焦「{focus}」。{reason} 正確答案為選項 {ans}：「{opts[ord(ans)-65]}」。"};d["solutionStrategy"]=f"先定位{focus}的制度、群體、時段與資料，再區分主張、實作和後果；{reason}"
 d["solutionSteps"]=[f"讀題定位：圈出共和、民族、民主、科學、財政、動員或制度落地線索，確認本題正在檢核「{focus}」。","建立判準：把理念主張、制度規則、治理實作與群體成本分層，並標記來源。",f"核對正解：選項 {ans}「{opts[ord(ans)-65]}」符合題幹，因為{reason}","逐項排除：檢查其餘選項是否把口號等同實況、把單一群體擴大成全體，或以事後結果抹平當時選擇。","結論回查：重新核對時間、地區、角色與證據強度；新增地方或民間材料後必須重新檢查。"]
 d["examPatternRefs"]=refs();d["updatedAt"]="2026-09-13";d["reviewStatus"]="draft";d["provenance"]["authoringNote"]="依官方課綱、歷 Ka 知識圖譜及三所公立學校公開社會科試題的國家形成、制度判讀與多方證據能力方向獨立改寫；未複製原題文字、選項、圖片或答案，待逐題學科與 Terra 複核。";p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(f"rewrote {len(ITEMS)} independent questions for {LESSON}")
